parameters.jsCode:
// Define esc first — used by both the guard and the main logic
const esc = (s) => String(s || '').replace(/'/g, "''");

// Pull upstream data once — used in both branches
const lead = $('Webhook').first().json.body;
const enrichment = $('Enrich Company').first().json;

// Build enrichment summary — same shape in both branches
const enrichmentSummary = JSON.stringify({
  social_links: enrichment.socialLinks || null,
  domain_age: enrichment.domainInfo?.domainAge || null,
  technologies: Array.isArray(enrichment.technologies) ? enrichment.technologies : [],
  rdap_registration: enrichment.domainInfo?.registrationDate || null
});

// Pull raw LLM output
const rawOutput = $input.first().json.output;

// Guard: empty output means the LLM failed (transient error, rate limit, etc.)
if (!rawOutput || String(rawOutput).trim() === '') {
  return {
    json: {
      name: esc(lead.name),
      email: esc(lead.email),
      company: esc(lead.company),
      message: esc(lead.message),
      score: 'low',
      criteria_met_sql: 'ARRAY[]::text[]',
      reasoning: 'Classification failed: LLM returned empty response. Manual review required.',
      enrichment_summary: enrichmentSummary
    }
  };
}

// Strip markdown fences and preamble that LLMs sometimes add
const cleaned = String(rawOutput)
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
const jsonString = jsonMatch ? jsonMatch[0] : cleaned;

const parsed = JSON.parse(jsonString);

// Normalize criteria_met to Title Case
const criteriaMetRaw = Array.isArray(parsed.criteria_met) ? parsed.criteria_met : [];
const criteriaMet = criteriaMetRaw.map(c =>
  String(c).toLowerCase().replace(/\b\w/g, l => l.toUpperCase())
);

// Build the Postgres array literal
const criteriaArrayLiteral = criteriaMet.length > 0
  ? 'ARRAY[' + criteriaMet.map(c => `'${esc(c)}'`).join(',') + ']::text[]'
  : 'ARRAY[]::text[]';

return {
  json: {
    name: esc(lead.name),
    email: esc(lead.email),
    company: esc(lead.company),
    message: esc(lead.message),
    score: parsed.score,
    criteria_met_sql: criteriaArrayLiteral,
    reasoning: esc(parsed.reasoning),
    enrichment_summary: enrichmentSummary
  }
};
